        if ($previousJoin = $this->getPreviousJoin()) {
            $join->setPreviousJoin($previousJoin);
        }

        // add the ModelJoin to the current object
        if ($relationAlias) {
            $this->addAlias($relationAlias, $relationMap->getRightTable()->getName());
            $this->addJoinObject($join, $relationAlias);
        } else {
            $this->addJoinObject($join, 'WorkflowInstance');
        }

        return $this;
    }

    /**
     * Use the WorkflowInstance relation WorkflowInstance object
     *
     * @see       useQuery()
     *
     * @param     string $relationAlias optional alias for the relation,
     *                                   to be used as main alias in the secondary query
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return   WorkflowInstanceQuery A secondary query class using the current class as primary query
     */
    public function useWorkflowInstanceQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinWorkflowInstance($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'WorkflowInstance', 'WorkflowInstanceQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   TimerEvent $timerEvent Object to remove from the list of results
     *
     * @return TimerEventQuery The current query, for fluid interface
     */
    public function prune($timerEvent = null)
    {
        if ($timerEvent) {
            $this->addUsingAlias(TimerEventPeer::TIMEREVENT_ID, $timerEvent->getTimereventId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

}
